        // Delphi: procedure TFormMain.SpeedButtonPrintClick(Sender: TObject)
        public void SpeedButtonPrintClick(object Sender)
        {
            if (Rtl.Pages(PageControlMain).ActivePage == TabSheetPanelView)
            {
                if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetDeviceSummary)
                {
                    {
                        // with PreviewPrinterMain do
                        PreviewPrinterMain.BeginDoc();
                        PreviewPrinterMain.Canvas.Lock();
                        {
                            // with self.PrintDialog do
                            PrintCalculateCurrentDevicePages();
                            this.PrintDialog.MinPage = 1;
                            this.PrintDialog.MaxPage = fPrintCols.PageCount;
                            if (this.PrintDialog.Execute())
                            {
                                PrintPrintCurrentDevicePages();
                                PreviewPrinterMain.EndDoc();
                                PreviewPrinterMain.Print();
                            }
                            else
                            {
                                Rtl.Abort();
                            }
                        }
                    }
                    return;
                }
                else if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetPanelLogs)
                {
                    {
                        // with PreviewPrinterMain do
                        PreviewPrinterMain.BeginDoc();
                        PreviewPrinterMain.Canvas.Lock();
                        {
                            // with self.PrintDialog do
                            PrintCalculateCurrentLogPages();
                            this.PrintDialog.MinPage = 1;
                            this.PrintDialog.MaxPage = fPrintCols.PageCount;
                            if (this.PrintDialog.Execute())
                            {
                                PrintPrintCurrentLogPages();
                                PreviewPrinterMain.EndDoc();
                                PreviewPrinterMain.Print();
                            }
                            else
                            {
                                Rtl.Abort();
                            }
                        }
                    }
                    return;
                }
            }
