                        }
                    }
                    finally
                    {
                        PreviewPrinterMain.Canvas.Unlock();
                    }
                    PreviewPrinterMain.EndDoc();
                    PreviewPrinterMain.Preview();
                }
                return;
            }
            {
                // with PreviewPrinterMain do
                PreviewPrinterMain.BeginDoc();
                {
                    // with self.PrintDialog do
                    PrintCalculateCols();
                    fPrintCols.CalculatingPageCount = true;
                    PrintPreparePages();
                    this.PrintDialog.MinPage = 1;
                    this.PrintDialog.MaxPage = fPrintCols.PageCount;
                    if (this.PrintDialog.Execute())
                    {
                        PrintCalculateCols();
                        fPrintCols.CalculatingPageCount = true;
