        // Delphi: procedure TFormMain.SpeedButtonPrintPreviewClick(Sender: TObject)
        public void SpeedButtonPrintPreviewClick(object Sender)
        {
            if (Rtl.Pages(PageControlMain).ActivePage == TabSheetPanelView)
            {
                if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetDeviceSummary)
                {
                    {
                        // with PreviewPrinterMain do
                        PreviewPrinterMain.BeginDoc();
                        PreviewPrinterMain.Canvas.Lock();
                        try
                        {
                            PrintCurrentDevicePages();
                        }
                        finally
                        {
                            PreviewPrinterMain.Canvas.Unlock();
                        }
                        PreviewPrinterMain.EndDoc();
                        PreviewPrinterMain.Preview();
                    }
                    return;
                }
                else if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetPanelLogs)
                {
                    {
                        // with PreviewPrinterMain do
                        PreviewPrinterMain.BeginDoc();
                        PreviewPrinterMain.Canvas.Lock();
                        try
                        {
                            PrintCurrentLogPages();
                        }
                        finally
                        {
                            PreviewPrinterMain.Canvas.Unlock();
                        }
                        PreviewPrinterMain.EndDoc();
                        PreviewPrinterMain.Preview();
                    }
                    return;
                }
            }
            else if (Rtl.Pages(PageControlMain).ActivePage == TabSheetCauseAndEffects)
            {
                {
                    // with PreviewPrinterMain do
                    PreviewPrinterMain.BeginDoc();
                    PreviewPrinterMain.Canvas.Lock();
                    try
                    {
                        PrintCETree();
                    }
                    finally
                    {
                        PreviewPrinterMain.Canvas.Unlock();
                    }
                    PreviewPrinterMain.EndDoc();
                    PreviewPrinterMain.Preview();
                }
                return;
            }
            {
                // with PreviewPrinterMain do
                PreviewPrinterMain.BeginDoc();
                PrintPages();
                PreviewPrinterMain.EndDoc();
                PreviewPrinterMain.Preview();
            }
        }

