        // Delphi: procedure TFormMain.PanelSiteDetailsResize(Sender: TObject)
        public void PanelSiteDetailsResize(object Sender)
        {
            int iWidth = 0;
            iWidth = (Rtl.GetClientWidth(PanelSiteDetails) - Rtl.GetWidth(GroupBoxLogo) - 4 * Rtl.GetLeft(GroupBoxClient)) / 2;
            Rtl.SetWidth(GroupBoxClient, iWidth);
            Rtl.SetWidth(GroupBoxInstaller, iWidth);
            Rtl.SetLeft(GroupBoxInstaller, 2 * Rtl.GetLeft(GroupBoxClient) + iWidth);
            Rtl.SetLeft(GroupBoxLogo, Rtl.GetLeft(GroupBoxInstaller) + iWidth + Rtl.GetLeft(GroupBoxClient));
            Rtl.SetWidth(GroupBoxGeneral, Rtl.GetWidth(GroupBoxInstaller));
            Rtl.SetLeft(GroupBoxSiteNotes, Rtl.GetLeft(GroupBoxInstaller));
            Rtl.SetWidth(GroupBoxSiteNotes, Rtl.GetLeft(GroupBoxLogo) + Rtl.GetWidth(GroupBoxLogo) - Rtl.GetLeft(GroupBoxInstaller));
        }

