                    {
                        if (Rtl.GetText(EditPanelName) != "")
                        {
                            Rtl.SetText(EditPanelName, "");
                        }
                    }
                    else
                    {
                        if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetDeviceSummary)
                        {
                            ShowDeviceSummary();
                            ShowZoneDeviceSummary();
                        }
                    }
                }
                fSigFile.ResetSelectedDevice();
            }
            else if (Rtl.Pages(PageControlMain).ActivePage == TabSheetNetworkView)
            {
                fSigFile.ZoneList.UpdateEditors();
                fSigFile.CauseAndEffects.InputGroups.UpdateEditors();
                if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetGlobalModes)
                {
                    null /* OnChange */(this);
