                {
                    null /* OnChange */(this);
                }
                else if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetGlobalInputGroups)
                {
                    null /* OnChange */(this);
                }
                else if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetInputSuperGroups)
                {
                    null /* OnChange */(this);
                }
                else if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetGlobalOutputGroups)
                {
