                }
                else if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetSuperGroups)
                {
                    null /* OnChange */(this);
                }
                else if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetSequences)
                {
                    null /* OnChange */(this);
                }
                else if (Rtl.Pages(PageControlNetworkView).ActivePage == TabSheetPulsePatterns)
