        // Delphi: procedure TFormMain.ComboBoxMaintenanceMonthChange(Sender: TObject)
        public void ComboBoxMaintenanceMonthChange(object Sender)
        {
            if (Rtl.GetItemIndex(ComboBoxMaintenanceMonth) != -1)
            {
                if (Rtl.GetItemIndex(ComboBoxMaintenanceMonth) != CalendarMaintenanceDate.Month - 1)
                {
                    try
                    {
                        CalendarMaintenanceDate.Month = Rtl.GetItemIndex(ComboBoxMaintenanceMonth) + 1;
                    }
                    catch (Exception)
                    {
                        CalendarMaintenanceDate.Day = 1;
                        CalendarMaintenanceDate.Month = Rtl.GetItemIndex(ComboBoxMaintenanceMonth) + 1;
                    }
                }
            }
        }

