        // Delphi: procedure TFormMain.PageControlPanelViewChange(Sender: TObject)
        public void PageControlPanelViewChange(object Sender)
        {
            {
                // with PageControlPanelView do
                if (Rtl.Pages(PageControlMain).ActivePage == TabSheetPanelView && Rtl.Pages(PageControlPanelView).ActivePage == TabSheetPanelLogs)
                {
                    Rtl.SetCaption(SpeedButtonRetrieveAllData, Translate("Retrieve Log"));
                    Rtl.SetEvent(SpeedButtonRetrieveAllData, "OnClick", SpeedButtonRetrieveLogClick);
                    Rtl.SetVisible(SpeedButtonSendAllToPanel, false);
                    Rtl.SetVisible(SpeedButtonRetrieveDeviceData, false);
                    Rtl.SetEvent(SpeedButtonNew, "OnClick", SpeedButtonEraseLogClick);
                    Rtl.SetEvent(SpeedButtonOpen, "OnClick", Import1Click);
                }
                else
                {
                    Rtl.SetCaption(SpeedButtonRetrieveAllData, Translate("Retrieve All Data"));
                    Rtl.SetEvent(SpeedButtonRetrieveAllData, "OnClick", SpeedButtonRetrieveAllDataClick);
                    Rtl.SetVisible(SpeedButtonSendAllToPanel, true);
                    Rtl.SetVisible(SpeedButtonRetrieveDeviceData, true);
                    Rtl.SetEvent(SpeedButtonNew, "OnClick", SpeedButtonNewClick);
                    Rtl.SetEvent(SpeedButtonOpen, "OnClick", SpeedButtonOpenClick);
                }
                if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetDeviceSummary)
                {
                    ShowDeviceSummary();
                    ShowZoneDeviceSummary();
                }
                else if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetLoops)
                {
                    fSigFile.ResetSelectedDevice();
                    fSigFile.NodeList.ActiveNode.RefreshEditors();
                    About.AboutBox.ShowVersion(fSigFile);
                }
                else if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetNetworkView)
                {
                    PageControlNetworkViewChange(Sender);
                }
                else if (Rtl.Pages(PageControlPanelView).ActivePage == TabSheetGlobalProperties)
                {
                    fSigFile.NodeList.RefreshEditors();
                }
            }
        }

