            {
                UnitExpertModes.ExpertModes = Rtl.SetUnion(UnitExpertModes.ExpertModes, new HashSet<TExpertMode> { TExpertMode.em_Show_ValidationButtons });
                Rtl.SetVisible(SpeedButtonVerifyAll, true);
                Rtl.SetVisible(SpeedButtonVerify, true);
                if (UnitExpertModes.ErrorReportingLevel == TErrorReportingLevel.el_None)
                {
                    Rtl.SetItemIndex(RadioGroupErrorsAndWarning, (int)TErrorReportingLevel.el_Errors);
                    RadioGroupErrorsAndWarningClick(Sender);
                }
            }
            else
            {
                UnitExpertModes.ExpertModes = Rtl.SetDifference(UnitExpertModes.ExpertModes, new HashSet<TExpertMode> { TExpertMode.em_Show_ValidationButtons });
