        // Delphi: procedure TFormMain.OnPanelSendAll(const pSender: integer; const pVerify, pIsSingle: boolean)
        internal void OnPanelSendAll(int pSender, bool pVerify, bool pIsSingle)
        {
            fErrorLists.ErrorList = null;
            try
            {
                if (pIsSingle || pSender == 0)
                {
                    fSigFile.ClearReportedErrorFlags();
                    Errors.Clear();
                }
                try
                {
                    UnitASCIITransfer.FormASCIITransfer.SendAllData(fSigFile.NodeList.Node[pSender], Errors, pVerify);
                }
                catch (Exception)
                {
                    switch (UnitExpertModes.ErrorReportingLevel)
                    {
                        case TErrorReportingLevel.elErrors_Warnings_Hints:
                            {
                            }
                            break;
                        case TErrorReportingLevel.el_Errors_Warnings:
                            {
                                Errors.ClearHints();
                            }
                            break;
                        case TErrorReportingLevel.el_Errors:
                            {
                                Errors.ClearWarningsAndHints();
                            }
                            break;
                        case TErrorReportingLevel.el_None:
                            {
                                Errors.Clear();
                            }
                            break;
                    }
                }
            }
            finally
            {
                if (pIsSingle || pSender == fSigFile.NodeList.Max)
                {
                    if (Errors.Count > 0)
                    {
                        fErrorLists.ErrorList = Errors;
                    }
                    if (Errors.ErrorCount > 0)
                    {
                        throw new Exception(Translate("Errors Found"));
                    }
                    else if (Errors.WarningCount > 0)
                    {
                        Rtl.MessageDlg(Translate("Warnings Found"), Rtl.mtWarning, new HashSet<TMsgDlgBtn> { Rtl.mbOK }, 0);
                    }
                    else if (Errors.HintCount > 0)
                    {
                        Rtl.MessageDlg(Translate("Hints Found"), Rtl.mtInformation, new HashSet<TMsgDlgBtn> { Rtl.mbOK }, 0);
                    }
                    else if (pVerify)
                    {
                        Rtl.MessageDlg(Translate("Verification Complete"), Rtl.mtInformation, new HashSet<TMsgDlgBtn> { Rtl.mbOK }, 0);
                    }
                    else
                    {
                        Rtl.MessageDlg(Translate("Transmission Complete"), Rtl.mtInformation, new HashSet<TMsgDlgBtn> { Rtl.mbOK }, 0);
                    }
                }
            }
        }

