        // Delphi: procedure TFormMain.ShowExpertModes
        public void ShowExpertModes()
        {
            bool iCustomMode = false;
            if (Rtl.SetEquals(UnitExpertModes.ExpertModes, UnitExpertModes.em_Simple))
            {
                Rtl.SetItemIndex(RadioGroupEditMode, 0);
                iCustomMode = false;
            }
            else if (Rtl.SetEquals(UnitExpertModes.ExpertModes, UnitExpertModes.em_Expert))
            {
                Rtl.SetItemIndex(RadioGroupEditMode, 1);
                iCustomMode = false;
            }
            else
            {
                Rtl.SetItemIndex(RadioGroupEditMode, 2);
                iCustomMode = true;
            }
            ShowExpertCheckBoxes(iCustomMode);
        }

        // Delphi: procedure TFormMain.ShowExpertCheckBoxes(const iCustomMode: boolean)
        public void ShowExpertCheckBoxes(bool iCustomMode)
        {
            Rtl.SetChecked(CheckBoxFullXferOptions, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Show_Advanced_Send_Rcv));
            Rtl.SetEnabled(CheckBoxFullXferOptions, iCustomMode);
            Rtl.SetChecked(CheckBoxUseThreads, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Use_Threading));
            Rtl.SetEnabled(CheckBoxUseThreads, iCustomMode);
            Rtl.SetChecked(CheckBoxCheckUSBStatus, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Check_USB_Status));
            Rtl.SetEnabled(CheckBoxCheckUSBStatus, iCustomMode);
            Rtl.SetChecked(CheckBoxUseFullDictionaries, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Use_Full_Dictionaries));
            Rtl.SetChecked(CheckBoxCfgAcrossNetwork, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Allow_Cfg_from_remote_panels));
            Rtl.SetChecked(CheckBoxViewLogAsTable, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_View_Log_as_Table));
            Rtl.SetEnabled(CheckBoxUseFullDictionaries, iCustomMode);
            Rtl.SetChecked(CheckBoxAllFileTransfersToPanel, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Allow_File_Transfer));
            Rtl.SetEnabled(CheckBoxAllFileTransfersToPanel, iCustomMode);
            Rtl.SetChecked(CheckBoxAllowImportExport, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Show_Import_Export));
            Rtl.SetEnabled(CheckBoxAllowImportExport, iCustomMode);
            Rtl.SetChecked(CheckBoxAutoReload, UnitExpertModes.ExpertModes.Contains(TExpertMode.em_Auto_Reload_Last_Saved_File));
            Rtl.SetEnabled(CheckBoxAllowImportExport, true);
        }

